-- Agent report drill-down and supervisor dashboard. Apply after 023.
begin;
do $$begin if not exists(select 1 from public.jf_schema_versions where version='023_unified_order_lists') then raise exception 'Apply migration 023 first.';end if;end$$;
create function public.jf_agent_report(target_shop uuid,target_agent uuid default null,report_start timestamptz default null,report_end timestamptz default null) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare result jsonb; filters jsonb:=jsonb_build_object('report_start',report_start,'report_end',report_end);agent_id uuid:=target_agent;search text:='';
begin
 if not jioflow_private.manages_shop(target_shop) then raise exception 'Agent reporting access denied.' using errcode='42501';end if;
 if target_agent is not null and not exists(select 1 from public.jf_memberships where id=target_agent and shop_id=target_shop and role='agent' and status<>'removed') then raise exception 'Agent not found in this business.' using errcode='42501';end if;
 if report_start is not null and report_end is not null and report_start>=report_end then raise exception 'Invalid reporting period.';end if;
with live as materialized(select o.* from public.jf_orders o where o.shop_id=target_shop and o.archived_at is null and (agent_id is null or o.assigned_membership_id=agent_id)
   and (nullif(filters->>'report_start','') is null or o.created_at>=(filters->>'report_start')::timestamptz) and (nullif(filters->>'report_end','') is null or o.created_at<(filters->>'report_end')::timestamptz) and (coalesce(filters->>'source','')='' or case when lower(o.source) in('website','facebook','whatsapp') then lower(o.source) else 'other' end=filters->>'source') and (nullif(filters->>'product_id','') is null or exists(select 1 from public.jf_order_items i where i.shop_id=target_shop and i.order_id=o.id and i.product_id=(filters->>'product_id')::uuid)) and (coalesce(filters->>'tag','')='' or exists(select 1 from public.jf_customers c where c.shop_id=target_shop and c.id=o.customer_id and c.unassignment_tag=filters->>'tag')) and (coalesce(filters->>'response','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=o.customer_id and f.call_outcome=lower(filters->>'response'))) and (coalesce(filters->>'call','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=o.customer_id and (lower(replace(filters->>'call',' ','_'))='connected' and f.call_outcome in('connected','positive','negative','intermediate') or lower(replace(filters->>'call',' ','_'))='not_connected' and f.call_outcome in('not_connected','no_answer','busy')))) and (search='' or o.order_number ilike '%'||search||'%' or o.recipient_name ilike '%'||search||'%' or o.recipient_phone ilike '%'||search||'%')),history as materialized(select h.id,h.external_id order_number,c.full_name recipient_name,c.phone recipient_phone,c.address delivery_address,c.source,c.assigned_membership_id,h.customer_id,h.updated_at created_at,h.updated_at,case lower(replace(coalesce(h.details->>'status','imported'),' ','_')) when 'pending' then 'draft' when 'draft' then 'draft' when 'confirmed' then 'confirmed' when 'ready_to_book' then 'ready_to_book' when 'booked' then 'booked' when 'in_transit' then 'in_transit' when 'delivered' then 'delivered' when 'completed' then 'delivered' when 'complete' then 'delivered' when 'returned' then 'returned' when 'cancelled' then 'cancelled' when 'canceled' then 'cancelled' when 'partial_delivery' then 'partial_delivery' else 'imported' end status,true is_imported,h.details,case when coalesce(h.details->>'total','') ~ '^[0-9]+([.][0-9]+)?$' then (h.details->>'total')::numeric else 0 end total
   from public.jf_order_history h join public.jf_customers c on c.shop_id=h.shop_id and c.id=h.customer_id where h.shop_id=target_shop and c.archived_at is null and (agent_id is null or c.assigned_membership_id=agent_id)
   and (nullif(filters->>'report_start','') is null or h.updated_at>=(filters->>'report_start')::timestamptz) and (nullif(filters->>'report_end','') is null or h.updated_at<(filters->>'report_end')::timestamptz)
   and (coalesce(filters->>'source','')='' or lower(c.source)=lower(filters->>'source')) and (coalesce(filters->>'tag','')='' or c.unassignment_tag=filters->>'tag') and nullif(filters->>'product_id','') is null and (coalesce(filters->>'response','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=c.id and f.call_outcome=lower(filters->>'response'))) and (coalesce(filters->>'call','')='' or exists(select 1 from public.jf_followups f where f.shop_id=target_shop and f.customer_id=c.id and (lower(replace(filters->>'call',' ','_'))='connected' and f.call_outcome in('connected','positive','negative','intermediate') or lower(replace(filters->>'call',' ','_'))='not_connected' and f.call_outcome in('not_connected','no_answer','busy'))))
   and (search='' or h.external_id ilike '%'||search||'%' or c.full_name ilike '%'||search||'%' or c.phone ilike '%'||search||'%')),orders as materialized(select l.customer_id,l.assigned_membership_id,l.status,l.total,l.created_at,false is_imported from live l union all select h.customer_id,h.assigned_membership_id,h.status,h.total,h.created_at,true is_imported from history h where not exists(select 1 from live l where l.order_number=h.order_number)),
 c as(select c.assigned_membership_id id,count(*) filter(where true) assigned,count(*) filter(where f.status='completed') completed,count(*) filter(where coalesce(f.status,'pending') in('pending','callback')) pending,count(*) filter(where f.status='cancelled') cancelled,count(*) filter(where f.call_outcome is not null and f.call_outcome<>'not_attempted') attempted,count(*) filter(where f.call_outcome is null or f.call_outcome='not_attempted') not_attempted,count(*) filter(where f.call_outcome in('connected','positive','negative','intermediate')) connected,count(*) filter(where f.call_outcome in('not_connected','no_answer','busy')) not_connected,count(*) filter(where f.status='callback' and f.callback_at<=now()) callbacks,count(*) filter(where c.permanent) permanent,count(*) filter(where f.call_outcome='positive') positive,count(*) filter(where f.call_outcome='negative') negative,count(*) filter(where f.call_outcome='intermediate') intermediate,count(*) filter(where f.status='completed' and exists(select 1 from orders o where o.customer_id=c.id and o.status not in('draft','cancelled','imported'))) buyers from public.jf_customers c left join public.jf_followups f on f.shop_id=c.shop_id and f.customer_id=c.id where c.shop_id=target_shop and c.archived_at is null group by c.assigned_membership_id),
 o as(select assigned_membership_id id,count(*) filter(where true) orders,count(*) filter(where status not in('draft','cancelled','imported')) confirmed,count(*) filter(where status='delivered') delivered,count(*) filter(where status='returned') returned,count(*) filter(where status='cancelled') cancelled_orders,count(*) filter(where status='draft') draft,count(*) filter(where status='booked') booked,count(*) filter(where status='in_transit') in_transit,count(*) filter(where status in('confirmed','ready_to_book')) ready_to_book,count(*) filter(where is_imported) imported,coalesce(sum(total) filter(where status not in('draft','cancelled','imported')),0) revenue from orders group by assigned_membership_id)
 select jsonb_build_object('agents',coalesce(jsonb_agg(jsonb_build_object('id',m.id,'user_id',m.user_id,'name',p.full_name,'email',p.email,'code',p.user_code,'avatar',p.avatar_path,'active',p.active and m.status='active','assigned',coalesce(c.assigned,0),'completed',coalesce(c.completed,0),'pending',coalesce(c.pending,0),'cancelled',coalesce(c.cancelled,0),'attempted',coalesce(c.attempted,0),'not_attempted',coalesce(c.not_attempted,0),'connected',coalesce(c.connected,0),'not_connected',coalesce(c.not_connected,0),'callbacks',coalesce(c.callbacks,0),'permanent',coalesce(c.permanent,0),'positive',coalesce(c.positive,0),'negative',coalesce(c.negative,0),'intermediate',coalesce(c.intermediate,0),'orders',coalesce(o.orders,0),'confirmed',coalesce(o.confirmed,0),'delivered',coalesce(o.delivered,0),'returned',coalesce(o.returned,0),'cancelled_orders',coalesce(o.cancelled_orders,0),'draft',coalesce(o.draft,0),'booked',coalesce(o.booked,0),'in_transit',coalesce(o.in_transit,0),'ready_to_book',coalesce(o.ready_to_book,0),'imported',coalesce(o.imported,0),'revenue',coalesce(o.revenue,0),'buyers',coalesce(c.buyers,0),'purchase_rate',case when coalesce(c.completed,0)=0 then 0 else 100.0*c.buyers/c.completed end) order by p.full_name),'[]'::jsonb)) into result from public.jf_memberships m join public.jf_profiles p on p.id=m.user_id left join c on c.id=m.id left join o on o.id=m.id where m.shop_id=target_shop and m.role='agent' and m.status<>'removed' and p.deleted_at is null and (target_agent is null or m.id=target_agent);
 if target_agent is not null then
 result:=result||jsonb_build_object('activity',coalesce((select jsonb_agg(to_jsonb(e) order by e.at desc) from(
 select * from(select 'followup' kind,e.created_at at,e.outcome status,e.note,c.id customer_id,c.full_name customer_name,c.phone from public.jf_followup_events e join public.jf_followups f on f.shop_id=e.shop_id and f.id=e.followup_id join public.jf_customers c on c.shop_id=f.shop_id and c.id=f.customer_id where e.shop_id=target_shop and e.actor_id=(select user_id from public.jf_memberships where id=target_agent) and (report_start is null or e.created_at>=report_start) and (report_end is null or e.created_at<report_end) order by e.created_at desc limit 30) f
 union all
 select * from(select 'order' kind,e.created_at at,e.status,e.note,o.customer_id,o.recipient_name customer_name,o.recipient_phone phone from public.jf_order_events e join public.jf_orders o on o.shop_id=e.shop_id and o.id=e.order_id where e.shop_id=target_shop and e.actor_id=(select user_id from public.jf_memberships where id=target_agent) and (report_start is null or e.created_at>=report_start) and (report_end is null or e.created_at<report_end) order by e.created_at desc limit 30) o
 order by at desc limit 30)e),'[]'::jsonb));end if;
 return result;
end $$;
revoke all on function public.jf_agent_report(uuid,uuid,timestamptz,timestamptz) from public,anon,authenticated;
grant execute on function public.jf_agent_report(uuid,uuid,timestamptz,timestamptz) to authenticated;
insert into public.jf_schema_versions(version) values('024_agent_report_dashboard');commit;
